mapper.update:
UPDATE attendance_record
SET status        = 1,
    checkin_time  = #{checkinTime},
    longitude     = #{longitude},
    latitude      = #{latitude},
    update_time   = NOW()
WHERE id = #{id}
  AND session_id = #{sessionId}
  AND student_id = #{studentId}
  AND status = 0

UPDATE attendance_record
SET status      = 5,
    checkin_time = #{checkinTime},
    update_time = NOW()
WHERE id = #{id}
  AND session_id = #{sessionId}
  AND student_id = #{studentId}
  AND status = 0

mapper.select:
SELECT COUNT(1)
FROM attendance_record
WHERE session_id = #{sessionId}
  AND student_id = #{studentId}
